/* @lc app=leetcode id=1203 lang=kotlin */ class Solution { fun topo(n: Int, es: List<List<Int>>): List<Int>? = es.distinct().let { de -> de.groupBy({ it[0] }, { it[1] }).let { adj -> IntArray(n).also { d -> de.forEach { d[it[1]]++ } }.let { d -> generateSequence((0 until n).filter { d[it] == 0 }) { f -> f.flatMap { u -> adj[u].orEmpty() }.filter { v -> --d[v] == 0 }.takeIf { it.isNotEmpty() } }.flatten().toList().takeIf { it.size == n } } } } fun sortItems(n: Int, m: Int, group: IntArray, beforeItems: List<List<Int>>): IntArray = group.indices.map { if (group[it] == -1) m + it else group[it] }.let { g -> beforeItems.flatMapIndexed { i, bs -> bs.map { listOf(it, i) } }.let { ie -> topo(n, ie)?.let { io -> topo(m + n, ie.filter { g[it[0]] != g[it[1]] }.map { listOf(g[it[0]], g[it[1]]) })?.let { go -> io.groupBy { g[it] }.let { byG -> go.flatMap { byG[it].orEmpty() }.toIntArray() } } } ?: intArrayOf() } } }